/* Offline prototype, using the same list/drawer interaction as ops-web. */
const categories=[{id:'FOOD',name:'食品',path:'食品'},{id:'FRUIT',name:'水果',path:'食品 / 水果'}];
const rows=[{scope:'DEFAULT',value:100,active:100,revision:1},{scope:'FOOD',value:200,active:200,revision:1}];
const $=id=>document.getElementById(id);
const name=r=>r.scope==='DEFAULT'?'默认规则':categories.find(c=>c.id===r.scope).name;
const percent=n=>n==null?'—':`${(n/100).toFixed(2)}%`;
function render(){ $('rows').replaceChildren(...rows.map(r=>{const tr=document.createElement('tr');tr.tabIndex=0;tr.setAttribute('role','button');[r.scope==='DEFAULT'?'默认':'品类',name(r),categories.find(c=>c.id===r.scope)?.path??'—','消费积分','HX_TOKEN',percent(r.active),r.active==null?'未生效':r.active===r.value?'生效中':'生效中 · 有草稿',r.revision].forEach(v=>{const td=document.createElement('td');td.textContent=String(v);tr.append(td);});tr.onclick=()=>detail(r);tr.onkeydown=e=>{if(e.key==='Enter')detail(r);};return tr;}));}
function open(title,body,actions){$('title').textContent=title;$('body').replaceChildren(body);$('actions').replaceChildren(...actions);$('layer').hidden=false;}
function close(){$('layer').hidden=true;render();}
function button(label,action){const b=document.createElement('button');b.textContent=label;b.className='ops-btn secondary';b.onclick=action;return b;}
function detail(r){const body=document.createElement('div');const p=document.createElement('p');p.textContent=`当前生效：${percent(r.active)}；待发布配置：${percent(r.value)}；修订 ${r.revision}。调整只影响新订单。`;body.append(p);const actions=[button('调整规则',()=>edit(r)),button('生效',()=>{if(confirm('新订单将使用本配置，已有订单不变。')){r.active=r.value;r.revision++;close();}})];if(r.scope!=='DEFAULT')actions.push(button('停用',()=>{if(confirm('停用后恢复上级或默认比例。')){r.active=null;r.revision++;close();}}));open(name(r),body,actions);}
function edit(r){const form=document.createElement('form');form.id='edit-rule';form.className='pv-form';form.innerHTML=`<label class="ops-field">适用品类<select class="ops-input" name="scope" ${r?'disabled':''} required>${r?.scope==='DEFAULT'?'<option value="DEFAULT">所有未单独配置的品类</option>':'<option value="">请选择品类</option>'+categories.map(c=>`<option value="${c.id}">${c.path}</option>`).join('')}</select></label><div class="pv-input-row"><label class="ops-field">赠送方式<select class="ops-input" name="mode"><option value="RATIO">按比例赠送</option><option value="NONE">不赠送</option></select></label><label class="ops-field" id="ratio-label">赠送比例（%）<input class="ops-input" name="ratio" type="number" min="0" max="100" step="0.01" value="${((r?.value??100)/100).toFixed(2)}" required></label></div><p class="pv-help">按商品现金实付计算，排除运费及积分抵扣。保存为草稿后需单独生效。</p><label class="ops-field">备注<input class="ops-input" name="remark" maxlength="500"></label>`;if(r)form.elements.scope.value=r.scope;form.elements.mode.onchange=()=>{$('ratio-label').hidden=form.elements.mode.value==='NONE';};form.onsubmit=e=>{e.preventDefault();const scope=r?.scope??form.elements.scope.value;if(!r&&rows.some(x=>x.scope===scope)){alert('该品类已有规则，请从列表调整。');return;}const value=form.elements.mode.value==='NONE'?0:Math.round(Number(form.elements.ratio.value)*100);if(r){r.value=value;r.revision++;}else rows.push({scope,value,active:null,revision:1});close();};const save=button('保存草稿',()=>{});save.type='submit';save.setAttribute('form','edit-rule');open(r?'调整赠送规则':'新增品类规则',form,[button('取消',close),save]);}
function preview(){const form=document.createElement('form');form.className='pv-form';form.innerHTML='<label class="ops-field">商品品类<select class="ops-input" name="category"><option value="FRUIT">食品 / 水果</option><option value="OTHER">其他品类</option></select></label><label class="ops-field">商品现金实付（人民币元）<input class="ops-input" name="cash" type="number" min="0" step="0.01" value="100" required></label><p class="pv-help">示例兑换配置：1 分人民币对应 1 积分。</p><p id="result"></p>';form.onsubmit=e=>{e.preventDefault();const match=(form.elements.category.value==='FRUIT'&&rows.find(r=>r.scope==='FRUIT'&&r.active!=null))||(form.elements.category.value==='FRUIT'&&rows.find(r=>r.scope==='FOOD'&&r.active!=null))||rows[0];const minor=Math.round(Number(form.elements.cash.value)*100);$('result').textContent=`命中${name(match)}，比例${percent(match.active)}，预计赠送 ${Math.floor(minor*match.active/10000)} 积分。`;};const run=button('计算预计积分',()=>{});run.type='submit';run.setAttribute('form','preview-form');form.id='preview-form';open('计算预览',form,[run]);}
$('new').onclick=()=>edit(null);$('preview').onclick=preview;$('close').onclick=close;document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});render();
